def solve(payload):
    capacity, rate = payload["capacity"], payload["refill_per_second"]
    tokens = payload.get("initial_tokens", capacity)
    if capacity <= 0 or rate < 0 or tokens < 0 or tokens > capacity:
        return {"error": "invalid_policy"}
    previous = 0
    allowed = []
    for request in payload["requests"]:
        now, cost = request["time"], request["cost"]
        if now < previous or now < 0 or cost <= 0:
            return {"error": "invalid_request"}
        tokens = min(capacity, tokens + (now - previous) * rate)
        accepted = tokens + 1e-12 >= cost
        if accepted:
            tokens = max(0.0, tokens - cost)
        allowed.append(accepted)
        previous = now
    return {"allowed": allowed, "remaining_tokens": tokens}

